// Server-side persistence for completed, backend-validated ProductBlueprintV1 results.
// This adapter is deliberately independent of browser clients and uses only the service-role key.
import type { ProductBlueprintV1 } from './contract.ts';
import { validateProductBlueprint } from './validate.ts';

export interface BlueprintResultIdentity {
  userId: string;
  clusterId: string;
  requestKeyHash: string;
  requestParams: Record<string, string>;
  model: string;
  configVersion: string;
}

export interface BlueprintResultStoreConfig {
  supabaseUrl: string;
  serviceRoleKey: string;
  fetchImpl?: typeof fetch;
}

export interface StoredBlueprintResult {
  id: string;
  created_at: string;
  blueprint: ProductBlueprintV1;
}

const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const SHA256 = /^[a-f0-9]{64}$/;

export class BlueprintResultStore {
  private readonly fetchImpl: typeof fetch;
  private readonly baseUrl: string;

  constructor(private readonly config: BlueprintResultStoreConfig) {
    if (!/^https:\/\//.test(config.supabaseUrl) || !config.serviceRoleKey) {
      throw new TypeError('invalid_blueprint_result_store_config');
    }
    this.fetchImpl = config.fetchImpl ?? fetch;
    this.baseUrl = config.supabaseUrl.replace(/\/$/, '') + '/rest/v1/dr_blueprints';
  }

  private assertIdentity(identity: BlueprintResultIdentity): void {
    if (!UUID.test(identity.userId) || !UUID.test(identity.clusterId)
      || !SHA256.test(identity.requestKeyHash)
      || !identity.model.endsWith(':free')
      || !identity.configVersion) {
      throw new TypeError('invalid_blueprint_result_identity');
    }
  }

  /** Returns the exact prior result for a retry; never searches by client-controlled data alone. */
  async get(identity: BlueprintResultIdentity): Promise<StoredBlueprintResult | null> {
    this.assertIdentity(identity);
    const query = new URLSearchParams({
      select: 'id,created_at,blueprint',
      user_id: 'eq.' + identity.userId,
      cluster_id: 'eq.' + identity.clusterId,
      request_key_hash: 'eq.' + identity.requestKeyHash,
      limit: '2',
    });
    const response = await this.fetchImpl(this.baseUrl + '?' + query.toString(), {
      method: 'GET',
      headers: {
        apikey: this.config.serviceRoleKey,
        authorization: 'Bearer ' + this.config.serviceRoleKey,
        accept: 'application/json',
      },
    });
    if (!response.ok) throw new Error('blueprint_result_read_failed:' + response.status);
    const rows: unknown = await response.json();
    if (!Array.isArray(rows)) throw new Error('blueprint_result_read_invalid_response');
    if (rows.length === 0) return null;
    if (rows.length !== 1) throw new Error('blueprint_result_identity_ambiguous');
    const row = rows[0];
    if (typeof row !== 'object' || row === null || Array.isArray(row)) {
      throw new Error('blueprint_result_read_invalid_response');
    }
    const value = row as Record<string, unknown>;
    if (typeof value.id !== 'string' || typeof value.created_at !== 'string') {
      throw new Error('blueprint_result_read_invalid_response');
    }
    const validated = validateProductBlueprint(value.blueprint);
    if (!validated.ok) throw new Error('blueprint_result_failed_validation');
    return { id: value.id, created_at: value.created_at, blueprint: validated.value };
  }

  /**
   * Atomically inserts the completed blueprint and commits its quota reservation in one database transaction.
   * If the response is lost after commit, a retry can read the result before touching quota.
   */
  async finalize(
    identity: BlueprintResultIdentity,
    reservationId: string,
    blueprint: ProductBlueprintV1,
  ): Promise<StoredBlueprintResult> {
    this.assertIdentity(identity);
    if (!UUID.test(reservationId)
      || blueprint.meta.contract_version !== 'product-blueprint.v1'
      || !SHA256.test(blueprint.meta.evidence_pack.pack_sha256)) {
      throw new TypeError('invalid_blueprint_finalization');
    }

    const response = await this.fetchImpl(
      this.config.supabaseUrl.replace(/\/$/, '') + '/rest/v1/rpc/dr_blueprint_finalize',
      {
        method: 'POST',
        headers: {
          apikey: this.config.serviceRoleKey,
          authorization: 'Bearer ' + this.config.serviceRoleKey,
          'content-type': 'application/json',
          accept: 'application/json',
        },
        body: JSON.stringify({
          p_reservation: reservationId,
          p_user: identity.userId,
          p_cluster: identity.clusterId,
          p_request_key_hash: identity.requestKeyHash,
          p_request_params: identity.requestParams,
          p_schema_version: blueprint.meta.contract_version,
          p_model: identity.model,
          p_config_version: identity.configVersion,
          p_evidence_pack_sha256: blueprint.meta.evidence_pack.pack_sha256,
          p_blueprint: blueprint,
        }),
      },
    );
    if (!response.ok) throw new Error('blueprint_atomic_finalize_failed:' + response.status);
    const result: unknown = await response.json();
    if (typeof result !== 'object' || result === null || Array.isArray(result)
      || (result as Record<string, unknown>).status !== 'completed'
      || typeof (result as Record<string, unknown>).id !== 'string'
      || !UUID.test((result as Record<string, unknown>).id as string)
      || typeof (result as Record<string, unknown>).created_at !== 'string') {
      throw new Error('blueprint_atomic_finalize_invalid_response');
    }

    const stored = await this.get(identity);
    if (!stored || stored.id !== (result as Record<string, unknown>).id) {
      throw new Error('blueprint_atomic_finalize_result_unavailable');
    }
    return stored;
  }

  async save(identity: BlueprintResultIdentity, blueprint: ProductBlueprintV1): Promise<{ id: string; created_at: string }> {
    this.assertIdentity(identity);
    if (blueprint.meta.contract_version !== 'product-blueprint.v1'
      || !SHA256.test(blueprint.meta.evidence_pack.pack_sha256)) {
      throw new TypeError('invalid_blueprint_result');
    }

    const query = new URLSearchParams({ on_conflict: 'user_id,cluster_id,request_key_hash' });
    const response = await this.fetchImpl(this.baseUrl + '?' + query.toString(), {
      method: 'POST',
      headers: {
        apikey: this.config.serviceRoleKey,
        authorization: 'Bearer ' + this.config.serviceRoleKey,
        'content-type': 'application/json',
        accept: 'application/vnd.pgrst.object+json',
        prefer: 'resolution=merge-duplicates,return=representation',
      },
      body: JSON.stringify({
        user_id: identity.userId,
        cluster_id: identity.clusterId,
        request_key_hash: identity.requestKeyHash,
        request_params: identity.requestParams,
        schema_version: blueprint.meta.contract_version,
        model: identity.model,
        config_version: identity.configVersion,
        evidence_pack_sha256: blueprint.meta.evidence_pack.pack_sha256,
        blueprint,
        updated_at: new Date().toISOString(),
      }),
    });
    if (!response.ok) {
      // Do not include response bodies: PostgREST errors can contain submitted data.
      throw new Error('blueprint_result_persistence_failed:' + response.status);
    }
    const row: unknown = await response.json();
    if (typeof row !== 'object' || row === null || Array.isArray(row)
      || typeof (row as Record<string, unknown>).id !== 'string'
      || typeof (row as Record<string, unknown>).created_at !== 'string') {
      throw new Error('blueprint_result_persistence_invalid_response');
    }
    return { id: (row as Record<string, string>).id, created_at: (row as Record<string, string>).created_at };
  }
}

// B10: isolated adapter for the Blueprint-only daily quota RPCs.
// No Gemini PRD quota tables or RPCs are used here.
import { canonicalJson } from '../collector/ai-common.ts';
import type { BlueprintRequestParams } from './contract.ts';

export interface BlueprintQuotaRpc {
  rpc<T>(name: string, args: Record<string, unknown>): Promise<T>;
}
export type BlueprintReservation =
  | { status: 'reserved'; reservation_id: string; reused: boolean }
  | { status: 'committed'; reservation_id: string; reused: true }
  | { status: 'limit_reached' };

const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

/** Binds a client retry key to the authenticated user, cluster and exact request parameters. */
export async function blueprintReservationKey(
  userId: string,
  clientRequestKey: string,
  clusterId: string,
  params: BlueprintRequestParams,
): Promise<string> {
  if (!UUID.test(userId) || !UUID.test(clusterId) || clientRequestKey.length < 8 || clientRequestKey.length > 128) {
    throw new TypeError('invalid_reservation_identity');
  }
  const canonical = canonicalJson({ user_id: userId, client_request_key: clientRequestKey, cluster_id: clusterId, params });
  const digest = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(canonical));
  return [...new Uint8Array(digest)].map((b) => b.toString(16).padStart(2, '0')).join('');
}

/** Strictly parses the JSON shape returned by dr_blueprint_reserve. */
export function readBlueprintReservation(value: unknown): BlueprintReservation | null {
  if (typeof value !== 'object' || value === null || Array.isArray(value)) return null;
  const row = value as Record<string, unknown>;
  if (row.status === 'limit_reached') return { status: 'limit_reached' };
  if ((row.status === 'reserved' || row.status === 'committed')
    && typeof row.reservation_id === 'string' && UUID.test(row.reservation_id)
    && typeof row.reused === 'boolean') {
    if (row.status === 'committed' && row.reused !== true) return null;
    return { status: row.status, reservation_id: row.reservation_id, reused: row.reused } as BlueprintReservation;
  }
  return null;
}

export async function reserveBlueprint(
  rpc: BlueprintQuotaRpc,
  userId: string,
  requestKey: string,
  dailyLimit: number,
): Promise<BlueprintReservation> {
  if (!UUID.test(userId) || !/^[a-f0-9]{64}$/.test(requestKey) || !Number.isSafeInteger(dailyLimit) || dailyLimit < 1) {
    throw new TypeError('invalid_quota_arguments');
  }
  const raw = await rpc.rpc<unknown>('dr_blueprint_reserve', {
    p_user: userId, p_request_key: requestKey, p_daily_limit: dailyLimit,
  });
  const parsed = readBlueprintReservation(raw);
  if (!parsed) throw new Error('invalid_quota_response');
  return parsed;
}

export async function commitBlueprint(rpc: BlueprintQuotaRpc, reservationId: string): Promise<boolean> {
  if (!UUID.test(reservationId)) throw new TypeError('invalid_reservation_id');
  const result = await rpc.rpc<unknown>('dr_blueprint_commit', { p_reservation: reservationId });
  return result === true;
}

export async function releaseBlueprint(rpc: BlueprintQuotaRpc, reservationId: string): Promise<boolean> {
  if (!UUID.test(reservationId)) throw new TypeError('invalid_reservation_id');
  const result = await rpc.rpc<unknown>('dr_blueprint_release', { p_reservation: reservationId });
  return result === true;
}

// Complete orchestration boundary for a Blueprint generation request.
// HTTP/auth/entitlement/privacy gates stay in the Edge Function; this service owns A/B/C and finalization.
import { runBlueprintLifecycle, type BlueprintLifecycleResult } from './lifecycle.ts';
import { finalizeBlueprintProduct } from './assembly.ts';
import type { BlueprintRequestParams, PassRecord } from './contract.ts';
import type { PreparedEvidence } from './evidence-types.ts';
import type { BlueprintResultIdentity, BlueprintResultStore } from './result-store.ts';
import type { BlueprintQuotaRpc } from './quota.ts';
import type { AiCacheStore } from '../collector/ai-common.ts';
import type { BlueprintProviderConfig } from './provider.ts';

export interface BlueprintGenerationInput {
  identity: BlueprintResultIdentity;
  dailyLimit: number;
  request: BlueprintRequestParams;
  evidence: PreparedEvidence;
  allowedVerdicts: string[];
  resultStore: BlueprintResultStore;
  quotaRpc: BlueprintQuotaRpc;
  cacheStore: AiCacheStore;
  provider: BlueprintProviderConfig;
  now?: () => Date;
  createId?: () => string;
}

/**
 * Runs the full retry-safe lifecycle. The injected finalizer always verifies, assembles, validates,
 * then calls the atomic result-store RPC; transient persistence errors propagate for safe retry.
 */
export function runBlueprintGeneration(input: BlueprintGenerationInput): Promise<BlueprintLifecycleResult> {
  return runBlueprintLifecycle({
    identity: input.identity,
    dailyLimit: input.dailyLimit,
    resultStore: input.resultStore,
    quotaRpc: input.quotaRpc,
    cacheStore: input.cacheStore,
    provider: input.provider,
    runtimeInput: {
      request: input.request,
      evidence: input.evidence,
      allowedVerdicts: input.allowedVerdicts,
    },
    finalize: (args: {
      identity: BlueprintResultIdentity;
      reservationId: string;
      passes: Parameters<typeof finalizeBlueprintProduct>[0]['passes'];
      passRecords: PassRecord[];
    }) => finalizeBlueprintProduct({
      ...args,
      request: input.request,
      evidence: input.evidence,
      resultStore: input.resultStore,
      ...(input.now ? { now: input.now } : {}),
      ...(input.createId ? { createId: input.createId } : {}),
    }),
  });
}

// Blueprint Phase B4: durable, cache-first pass orchestration.
// One invocation may make at most ONE live provider request. Cache hits can advance through
// already-completed passes; a live pass is persisted before the caller is told to continue.
import {
  aiInputHash, cachedCompute, type AiCacheKey, type AiCacheStore, type CachedOutcome,
} from '../collector/ai-common.ts';
import type { BlueprintRequestParams, PassAOutput, PassBOutput, PassCOutput, PassRecord } from './contract.ts';
import type { PreparedEvidence } from './evidence-types.ts';
import { runBlueprintPass, type BlueprintPass } from './pipeline.ts';
import type { BlueprintProviderConfig, BlueprintProviderUsage } from './provider.ts';
import { validateBlueprintPassOutput } from './validate.ts';

export const BLUEPRINT_CONFIG_VERSION = 'bp1.p1.s1';

export type StoredPassOutput = PassAOutput | PassBOutput | PassCOutput;
export interface BlueprintRuntimeInput {
  request: BlueprintRequestParams;
  evidence: PreparedEvidence;
  allowedVerdicts: string[];
}
export interface BlueprintPasses {
  A?: PassAOutput;
  B?: PassBOutput;
  C?: PassCOutput;
}
export type BlueprintStepResult =
  | { state: 'pass_completed'; completed: BlueprintPass; next: 'B' | 'C' | 'assemble'; from_cache: boolean; passes: BlueprintPasses; passRecords: PassRecord[]; cache_id: string; input_hash: string }
  | { state: 'busy' | 'cooldown' | 'deferred'; pass: BlueprintPass; reason?: string; passes: BlueprintPasses }
  | { state: 'ready_to_assemble'; passes: BlueprintPasses; passRecords: PassRecord[] };

const PASS_ORDER: readonly BlueprintPass[] = ['A', 'B', 'C'];
const asPass = (pass: BlueprintPass, value: unknown): StoredPassOutput | null => {
  const checked = validateBlueprintPassOutput(pass, value);
  return checked.ok ? checked.value as StoredPassOutput : null;
};

function revive(pass: BlueprintPass, value: unknown): StoredPassOutput | null {
  if (typeof value !== 'object' || value === null || Array.isArray(value)) return null;
  const record = value as Record<string, unknown>;
  if (record.pass !== pass) return null;
  return asPass(pass, record.output);
}

function usageRecord(usage: BlueprintProviderUsage): Record<string, unknown> {
  return { ...usage };
}

function readCachedProviderUsage(value: unknown): BlueprintProviderUsage | null {
  if (typeof value !== 'object' || value === null || Array.isArray(value)) return null;
  const row = value as Record<string, unknown>;
  const integer = (v: unknown) => typeof v === 'number' && Number.isSafeInteger(v) && v >= 0;
  const optionalNumber = (v: unknown) => v === null || (typeof v === 'number' && Number.isFinite(v) && v >= 0);
  const optionalString = (v: unknown) => v === null || typeof v === 'string';
  if (!integer(row.input_tokens) || !integer(row.output_tokens) || !optionalNumber(row.reasoning_tokens)
    || !optionalNumber(row.reported_cost_usd) || !optionalString(row.served_model)
    || !optionalString(row.provider) || !optionalString(row.response_id) || !integer(row.duration_ms)) return null;
  return {
    input_tokens: row.input_tokens as number,
    output_tokens: row.output_tokens as number,
    reasoning_tokens: row.reasoning_tokens as number | null,
    reported_cost_usd: row.reported_cost_usd as number | null,
    served_model: row.served_model as string | null,
    provider: row.provider as string | null,
    response_id: row.response_id as string | null,
    duration_ms: row.duration_ms as number,
  };
}

function nextPass(pass: BlueprintPass): 'B' | 'C' | 'assemble' {
  return pass === 'A' ? 'B' : pass === 'B' ? 'C' : 'assemble';
}

/**
 * Loads all available cached passes in order and performs no more than one live pass.
 * The endpoint must run authentication, entitlement and quota gates BEFORE calling this function.
 */
export async function runBlueprintStep(
  store: AiCacheStore,
  provider: BlueprintProviderConfig,
  input: BlueprintRuntimeInput,
  options: { configVersion?: string; leaseSeconds?: number } = {},
): Promise<BlueprintStepResult> {
  const configVersion = options.configVersion ?? BLUEPRINT_CONFIG_VERSION;
  const passes: BlueprintPasses = {};
  let upstreamA: string | undefined;
  let upstreamB: string | undefined;
  const passRecords: PassRecord[] = [];

  for (const pass of PASS_ORDER) {
    const inputHash = await aiInputHash({
      contract: 'product-blueprint.v1',
      pass,
      request: input.request,
      evidence: input.evidence.canonical_pack_json,
      upstream: pass === 'A' ? null : pass === 'B' ? { A: upstreamA } : { A: upstreamA, B: upstreamB },
    });
    const key: AiCacheKey = { task: 'blueprint', model: provider.model, configVersion, hash: inputHash };
    const liveUsage: { value: BlueprintProviderUsage | null } = { value: null };
    const outcome: CachedOutcome<StoredPassOutput> = await cachedCompute(
      store,
      key,
      async () => {
        const result = await runBlueprintPass(provider, {
          pass, request: input.request, evidence: input.evidence,
          allowedVerdicts: input.allowedVerdicts,
          ...(passes.A ? { passA: passes.A } : {}),
          ...(passes.B ? { passB: passes.B } : {}),
        });
        liveUsage.value = result.provider.usage;
        const output = result.output as StoredPassOutput;
        return {
          value: output,
          result: { pass, output },
          citations: [],
          usage: usageRecord(result.provider.usage),
        };
      },
      (stored) => revive(pass, stored),
      { leaseSeconds: options.leaseSeconds ?? 150 },
    );

    if (outcome.status === 'busy') return { state: 'busy', pass, passes };
    if (outcome.status === 'cooldown') return { state: 'cooldown', pass, passes };
    if (outcome.status === 'deferred') return { state: 'deferred', pass, reason: outcome.reason, passes };

    const output = asPass(pass, outcome.value);
    if (!output) return { state: 'deferred', pass, reason: 'cached_pass_failed_validation', passes };
    // A computed pass is usable only when its cache write is durable. Advancing after a failed
    // write would make retries repeat a paid-in-quota provider call and lose pass continuity.
    if (outcome.status === 'computed' && outcome.stored !== true) {
      return { state: 'deferred', pass, reason: 'pass_result_not_durable', passes };
    }
    const provenanceUsage = liveUsage.value ?? (outcome.status === 'hit' ? readCachedProviderUsage(outcome.usage) : null);
    passRecords.push({
      pass, cache_id: outcome.cacheId, input_hash: inputHash,
      served_model: provenanceUsage?.served_model ?? null, provider: provenanceUsage?.provider ?? null, finish_reason: null,
      prompt_tokens: provenanceUsage?.input_tokens ?? 0, completion_tokens: provenanceUsage?.output_tokens ?? 0,
      reasoning_tokens: provenanceUsage?.reasoning_tokens ?? null, reported_cost_usd: provenanceUsage?.reported_cost_usd ?? null,
      duration_ms: provenanceUsage?.duration_ms ?? 0, from_cache: outcome.status === 'hit',
    });

    if (pass === 'A') {
      passes.A = output as PassAOutput;
      upstreamA = await aiInputHash(output);
    } else if (pass === 'B') {
      passes.B = output as PassBOutput;
      upstreamB = await aiInputHash(output);
    } else {
      passes.C = output as PassCOutput;
    }

    // A live result ends this invocation. Cache hits may continue to the next pass.
    if (outcome.status === 'computed') {
      return {
        state: 'pass_completed', completed: pass, next: nextPass(pass),
        from_cache: false, passes, passRecords, cache_id: outcome.cacheId, input_hash: inputHash,
      };
    }
  }

  return { state: 'ready_to_assemble', passes, passRecords };
}

// Blueprint Engine Phase B2: one strict, non-streaming OpenRouter chat-completions call.
// This module performs no persistence, quota accounting, retries, logging of content, or provider fallback.
// The caller must enforce auth/entitlement/quota before reaching this boundary and cache only validated pass outputs.
import { isFreeModelSlug } from '../collector/ai-common.ts';

export const BLUEPRINT_CHAT_COMPLETIONS_ENDPOINT = 'https://openrouter.ai/api/v1/chat/completions';
export const BLUEPRINT_DEFAULT_MODEL = 'baidu/ernie-5.5-flash-preview:free';

export interface BlueprintProviderConfig {
  apiKey: string;
  model: string;
  timeoutMs: number;
  endpoint?: string;
  fetchImpl?: typeof fetch;
}

export interface BlueprintProviderUsage {
  input_tokens: number;
  output_tokens: number;
  reasoning_tokens: number | null;
  reported_cost_usd: number | null;
  served_model: string | null;
  provider: string | null;
  response_id: string | null;
  duration_ms: number;
}

export interface BlueprintProviderResult {
  output: Record<string, unknown>;
  usage: BlueprintProviderUsage;
}

export type BlueprintProviderErrorCode =
  | 'invalid_config'
  | 'timeout'
  | 'network'
  | 'rate_limited'
  | 'provider_unavailable'
  | 'provider_rejected'
  | 'provider_error'
  | 'invalid_response'
  | 'truncated_response';

export class BlueprintProviderError extends Error {
  constructor(
    public readonly code: BlueprintProviderErrorCode,
    public readonly httpStatus: number | null = null,
  ) {
    super(code);
    this.name = 'BlueprintProviderError';
  }
}

const isObject = (v: unknown): v is Record<string, unknown> =>
  typeof v === 'object' && v !== null && !Array.isArray(v);

const nonNegativeInteger = (v: unknown): number =>
  typeof v === 'number' && Number.isSafeInteger(v) && v >= 0 ? v : 0;

const optionalNonNegativeNumber = (v: unknown): number | null =>
  typeof v === 'number' && Number.isFinite(v) && v >= 0 ? v : null;

/** Validate at the boundary. No paid model slug or provider fallback is ever accepted. */
export function blueprintProviderConfigProblem(config: BlueprintProviderConfig): string | null {
  if (!config.apiKey.trim()) return 'OPENROUTER_API_KEY is not set';
  if (!isFreeModelSlug(config.model)) return 'BLUEPRINT_MODEL must be an explicit :free model';
  if (!Number.isInteger(config.timeoutMs) || config.timeoutMs < 1_000 || config.timeoutMs > 120_000) {
    return 'BLUEPRINT_PASS_TIMEOUT_MS is outside the supported safety bounds';
  }
  return null;
}

/**
 * Calls exactly one pass. The AbortController remains active through response-body parsing, so the deadline
 * covers the complete response rather than only receipt of response headers. Raw provider text is never
 * included in thrown errors.
 */
export async function callBlueprintProvider(
  config: BlueprintProviderConfig,
  input: { systemPrompt: string; userPayload: unknown; maxTokens: number },
  now: () => number = Date.now,
): Promise<BlueprintProviderResult> {
  if (blueprintProviderConfigProblem(config) !== null) throw new BlueprintProviderError('invalid_config');
  if (!Number.isInteger(input.maxTokens) || input.maxTokens < 1 || input.maxTokens > 32_000) {
    throw new BlueprintProviderError('invalid_config');
  }

  const started = now();
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), config.timeoutMs);
  let response: Response;
  let raw: unknown;
  try {
    response = await (config.fetchImpl ?? fetch)(config.endpoint ?? BLUEPRINT_CHAT_COMPLETIONS_ENDPOINT, {
      method: 'POST',
      headers: {
        authorization: `Bearer ${config.apiKey}`,
        'content-type': 'application/json',
        accept: 'application/json',
        'http-referer': 'https://demandradar.app',
        'x-title': 'DemandRadar',
      },
      body: JSON.stringify({
        model: config.model,
        temperature: 0.1,
        max_tokens: input.maxTokens,
        response_format: { type: 'json_object' },
        provider: { allow_fallbacks: false },
        messages: [
          { role: 'system', content: input.systemPrompt },
          { role: 'user', content: JSON.stringify(input.userPayload) },
        ],
      }),
      signal: controller.signal,
    });

    if (!response.ok) {
      if (response.status === 429) throw new BlueprintProviderError('rate_limited', 429);
      if (response.status >= 500) throw new BlueprintProviderError('provider_unavailable', response.status);
      if (response.status === 401 || response.status === 403 || response.status === 402) {
        throw new BlueprintProviderError('provider_rejected', response.status);
      }
      throw new BlueprintProviderError('provider_error', response.status);
    }

    try {
      raw = await response.json();
    } catch {
      throw new BlueprintProviderError('invalid_response', response.status);
    }
  } catch (error) {
    if (error instanceof BlueprintProviderError) throw error;
    if (controller.signal.aborted) throw new BlueprintProviderError('timeout');
    throw new BlueprintProviderError('network');
  } finally {
    clearTimeout(timer);
  }

  if (!isObject(raw)) throw new BlueprintProviderError('invalid_response', response.status);
  if (raw.error !== undefined && raw.error !== null) throw new BlueprintProviderError('provider_error', response.status);
  if (!Array.isArray(raw.choices) || !isObject(raw.choices[0])) {
    throw new BlueprintProviderError('invalid_response', response.status);
  }

  const choice = raw.choices[0];
  if (choice.finish_reason === 'length') throw new BlueprintProviderError('truncated_response', response.status);
  if (choice.finish_reason === 'content_filter' || choice.finish_reason === 'error') {
    throw new BlueprintProviderError('provider_error', response.status);
  }
  if (!isObject(choice.message) || typeof choice.message.content !== 'string' || !choice.message.content.trim()) {
    throw new BlueprintProviderError('invalid_response', response.status);
  }

  let parsed: unknown;
  try {
    parsed = JSON.parse(choice.message.content);
  } catch {
    throw new BlueprintProviderError('invalid_response', response.status);
  }
  if (!isObject(parsed)) throw new BlueprintProviderError('invalid_response', response.status);

  const usage = isObject(raw.usage) ? raw.usage : {};
  const details = isObject(usage.completion_tokens_details) ? usage.completion_tokens_details : {};
  const cost = optionalNonNegativeNumber(usage.cost);
  return {
    output: parsed,
    usage: {
      input_tokens: nonNegativeInteger(usage.prompt_tokens),
      output_tokens: nonNegativeInteger(usage.completion_tokens),
      reasoning_tokens: optionalNonNegativeNumber(details.reasoning_tokens),
      reported_cost_usd: cost,
      served_model: typeof raw.model === 'string' ? raw.model.slice(0, 120) : null,
      provider: typeof raw.provider === 'string' ? raw.provider.slice(0, 80) : null,
      response_id: typeof raw.id === 'string' ? raw.id.slice(0, 120) : null,
      duration_ms: Math.max(0, now() - started),
    },
  };
}

